namespace ghidra.framework.plugintool.dialog;

using static org.junit.Assert;



using org.junit;

using docking.action;
using ghidra.app.plugin.core.archive;
using ghidra.framework.main;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool.util;
using ghidra.test;
using ghidra.test;
using ghidra.util.classfinder;

/**
 * Test configure the Front End tool
 */
public class ManageFrontEndToolTest : AbstractGhidraHeadedIntegrationTest {

	private TestEnv env;
	private FrontEndTool tool;
	private FrontEndPlugin plugin;
	private ManagePluginsDialog managePluginsDialog;
	private PluginConfigurationModel pluginModel;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getFrontEndTool();
		plugin = getPlugin(tool, typeof(FrontEndPlugin));

		env.showFrontEndTool();
		showProvider();
	}

	/* @After */
	public void tearDown()
    {

		runSwing(() => {
			tool.setConfigChanged(false);
			managePluginsDialog.close();
		});
		env.dispose();
	}

	/* @Test */
	public void testOnlyFrontendablePluginsAreAvailable() {
		int count = 0;
		List<PluginDescription> allPluginDescriptions = pluginModel.getAllPluginDescriptions();
		foreach (PluginDescription pluginDescription in allPluginDescriptions) {
			assertTrue(typeof(ApplicationLevelPlugin).isAssignableFrom(pluginDescription.getPluginClass()));
			count++;
		}

		List<Class<ApplicationLevelPlugin>> classes = ClassSearcher.getClasses(typeof(ApplicationLevelPlugin));
		assertEquals(count, classes.size());
	}

	/* @Test */
	public void testSaveCloseProject()
    {

		Plugin p = getPlugin(tool, typeof(ArchivePlugin));
		assertNotNull(p);
		runSwing(() => {
			managePluginsDialog.close();
			tool.removePlugins(List.of(p));
		});

		showProvider();

		DockingActionIf action = getAction(tool, plugin.getName(), "Save Project");
		performAction(action, true);

		action = getAction(tool, plugin.getName(), "Close Project");
		performAction(action, true);
		assertFalse(managePluginsDialog.isVisible());
	}

	private void showProvider()
    {

		DockingActionIf action = getAction(tool, "Project Window", "Configure Tool");
		performAction(action, true);
		waitForSwing();
		runSwing(() => tool.showConfig(false, false));

		managePluginsDialog = tool.getManagePluginsDialog();
		pluginModel = managePluginsDialog.getPluginConfigurationModel();
	}
}
